(function(root){
 function mapURL(address,directions=false){return 'https://www.google.com/maps/'+(directions?'dir/?':'search/?')+new URLSearchParams(directions?{api:'1',destination:address}:{api:'1',query:address})}
 function csvRows(text){if(typeof text!=='string'||text.length>200000)throw Error('Paste a CSV under 200 KB.');const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('CSV has an unclosed quote.');row.push(field);if(row.some(v=>v.trim()))rows.push(row);return rows}
 function catalogCSV(text,catalog){const rows=csvRows(text),header=rows.shift()?.map(s=>s.trim().toLowerCase());if(header?.join(',')!=='id,price,stock,revision')throw Error('Use CSV columns: id,price,stock,revision.');if(!rows.length||rows.length>100)throw Error('Paste between 1 and 100 rows.');return rows.map(row=>{if(row.length!==4||row.some(v=>!v.trim()))throw Error('Each row needs all four values.');const [id,price,stock,revision]=row.map(Number),p=catalog.find(p=>p.id===id);if(!p||!Number.isSafeInteger(revision)||revision<0||!Number.isInteger(stock)||stock<0||stock>100000||!Number.isFinite(price)||price<.01||price>100000||Math.abs(price*100-Math.round(price*100))>.00001)throw Error('Check product ID, price, stock and revision.');return {...p,price,stock,revision,mrp:Math.max(p.mrp||price,price)}})}
 function bindInstall(button,env=root){const key='wc-installed-'+(env.location.pathname.startsWith('/shopkeeper/')?'owner':'customer'),mode=env.matchMedia('(display-mode: standalone)');let remembered=false;try{remembered=env.localStorage.getItem(key)==='yes'}catch{}function render(){if(mode.matches||env.navigator.standalone===true){remembered=true;try{env.localStorage.setItem(key,'yes')}catch{}}button.hidden=mode.matches||env.navigator.standalone===true||remembered}function installed(){remembered=true;try{env.localStorage.setItem(key,'yes')}catch{}render()}env.addEventListener('appinstalled',installed);env.addEventListener('beforeinstallprompt',()=>{remembered=false;try{env.localStorage.removeItem(key)}catch{}render()});mode.addEventListener?.('change',render);render();return {accepted:installed,render}}
 const api={mapURL,csvRows,catalogCSV,bindInstall};if(typeof module==='object')module.exports=api;else root.WCNext=api;
})(typeof window==='object'?window:this);
